public class GUPPriceDiscPriceAttributeGroupSearch extends RunBase
{
    private GUPPriceAttributeGroupSearchTmp priceAttributeGroupSearchTmp;

    private FromDate            fromDate;
    private ToDate              toDate;
    private CurrencyCode        currencyCode;
    private PriceDiscJournalNum journalNum;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        fromDate,
        toDate,
        currencyCode,
        journalNum,
        priceAttributeGroupSearchTmp
    #endmacro

}

Method.Source:
public Object dialog(DialogRunbase _dialog = null, boolean _forceOnClient = false)
{
    DialogRunbase   dialog = Dialog::newFormnameRunbase(formStr(GUPPriceDiscPriceAttributeGroupSearch),this);
    dialog = this.dialogInternal(dialog);
    return dialog;
}

public GUPPriceAttributeGroupSearchTmp parmPriceAttributeGroupSearchTmp(GUPPriceAttributeGroupSearchTmp _priceAttributeGroupSearchTmp = priceAttributeGroupSearchTmp)
{
    priceAttributeGroupSearchTmp = _priceAttributeGroupSearchTmp;

    return priceAttributeGroupSearchTmp;
}

public CurrencyCode parmCurrencyCode(CurrencyCode _currencyCode = currencyCode)
{
    currencyCode = _currencyCode;

    return currencyCode;
}

public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;

    return fromDate;
}

public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;

    return toDate;
}

public static GUPPriceDiscPriceAttributeGroupSearch construct()
{
    return new GUPPriceDiscPriceAttributeGroupSearch();
}

public static void main(Args  _args)
{
    if (!(_args.dataset() == tableNum(PriceDiscAdmTrans)))
    {
        throw error("@SYS18626");
    }

    PriceDiscAdmTrans                       priceDiscAdmTrans = _args.record();
    GUPPriceDiscPriceAttributeGroupSearch   priceDiscSearch = GUPPriceDiscPriceAttributeGroupSearch::construct();

    priceDiscSearch.getLast();
    if (!priceDiscAdmTrans.JournalNum)
    {
        FormRun  priceDiscTransForm = _args.caller();

        if (   !(priceDiscTransForm is FormRun)
               || !(priceDiscTransForm.args().caller() is FormRun))
        {
            throw error("@SYS18626");
        }

        FormRun         priceDiscTableForm = priceDiscTransForm.args().caller();
        FormDataSource  tableDataSource    = priceDiscTableForm.dataSource();

        if (tableDataSource.table() != tableNum(PriceDiscAdmTable))
        {
            throw error("@SYS18626");
        }
        else
        {
            PriceDiscAdmTable priceDiscAdmTable = tableDataSource.cursor();
            priceDiscSearch.initJournalNum(priceDiscAdmTable.JournalNum);
        }
    }
    else
    {
        priceDiscSearch.initJournalNum(priceDiscAdmTrans.JournalNum);
    }

    if (priceDiscSearch.prompt())
    {
        priceDiscSearch.runOperation();

        if (priceDiscAdmTrans.dataSource())
        {
            priceDiscAdmTrans.dataSource().research(true);
            priceDiscAdmTrans.dataSource().refresh();
        }
    }
}

public void run()
{
    PriceDiscAdmTrans priceDiscAdmTrans;
    PriceDiscTable priceDiscTable;
    RecordInsertList rilpriceDiscAdmTrans = new RecordInsertList(tableNum(PriceDiscAdmTrans));

    ttsbegin;

    QueryRun qRun = new QueryRun(this.buildQuery());

    while (qRun.next())
    {
        priceDiscTable = qRun.get(tableNum(PriceDiscTable));

        priceDiscAdmTrans.clear();
        priceDiscAdmTrans.initFromPriceDiscTable(priceDiscTable);
        priceDiscAdmTrans.JournalNum = journalNum;

        rilpriceDiscAdmTrans.add(priceDiscAdmTrans);
    }

    rilpriceDiscAdmTrans.insertDatabase();
    this.reNumberLines();

    ttscommit;
}

protected void reNumberLines()
{
    DictTable                       dictPriceDiscAdmTrans = new DictTable(tableNum(PriceDiscAdmTrans));
    str                             sqlStmt;
    SqlSystem                       sqlSystem = new SqlSystem();
    str                             dataareaid;

    /* Test run dump from the debugger  -  this is what the direct sql is doing.

        IF OBJECT_ID(N'TEMPDB..#PRICEDISCTABLEREFTMP_3_34130') IS NOT NULL
        DROP TABLE #PRICEDISCTABLEREFTMP_3_34130

        SELECT  RECID AS PriceDiscTableRefRecId,
        Identity(int,1,1) AS LineNum
        INTO #PRICEDISCTABLEREFTMP_3_34130
        FROM PRICEDISCADMTRANS
        WHERE DATAAREAID = N'dmo'
        AND   JOURNALNUM = N'DMO-000006'
        AND   PARTITION = 5637144576
        ORDER BY ItemCode, ItemRelation, UnitId, Relation, AccountCode, FromDate

        UPDATE PRICEDISCADMTRANS
        SET    LINENUM = S1.LineNum
        FROM   PRICEDISCADMTRANS S,
        #PRICEDISCTABLEREFTMP_3_34130 S1
        WHERE  S.RECID = S1.PriceDiscTableRefRecId
        AND    S.JOURNALNUM = N'DMO-000006'
        AND    S.DATAAREAID = N'dmo'
        AND    S.PARTITION = 5637144576

        IF OBJECT_ID(N'TEMPDB..#PRICEDISCTABLEREFTMP_3_34130') IS NOT NULL
        DROP TABLE #PRICEDISCTABLEREFTMP_3_34130
        */

    sqlStmt     =   'IF OBJECT_ID(N\'TEMPDB..#PRICEDISCTABLEREFTMP_%1\') IS NOT NULL\n';
    sqlStmt     +=  '   DROP TABLE #PRICEDISCTABLEREFTMP_%1\n';
    sqlStmt     +=  '\n';
    sqlStmt     +=  ' SELECT  '+dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,RecId),DbBackend::Sql)+' AS PriceDiscTableRefRecId,\n';
    sqlStmt     +=  '        Identity(int,1,1) AS LineNum\n';
    sqlStmt     +=  '        INTO #PRICEDISCTABLEREFTMP_%1\n';
    sqlStmt     +=  '        FROM '+ dictPriceDiscAdmTrans.name(DbBackend::Sql)+'\n';
    sqlStmt     +=  '        WHERE '+ dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,DataAreaId),DbBackend::Sql)+' = %2\n';
    sqlStmt     +=  '        AND   '+ dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,JournalNum),DbBackend::Sql)+' = %3\n';
    sqlStmt     +=  '        AND   '+ dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,Partition),DbBackend::Sql)+' = %4\n';
    sqlStmt     +=  '        ORDER BY ITEMCODE, ITEMRELATION, UNITID, RELATION, ACCOUNTCODE, FROMDATE\n';
    sqlStmt     +=  '\n';
    sqlStmt     +=  'UPDATE '+ dictPriceDiscAdmTrans.name(DbBackend::Sql)+'\n';
    sqlStmt     +=  '       SET    '+dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,LineNum),DbBackend::Sql)+ ' = S1.LineNum\n';
    sqlStmt     +=  '       FROM   '+dictPriceDiscAdmTrans.name(DbBackend::Sql)+' S,\n';
    sqlStmt     +=  '       #PRICEDISCTABLEREFTMP_%1 S1\n';
    sqlStmt     +=  '       WHERE  S.'+dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,RecId),DbBackend::Sql)+' = S1.PriceDiscTableRefRecId\n';
    sqlStmt     +=  '       AND    S.'+dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,JournalNum),DbBackend::Sql)+' = %3\n';
    sqlStmt     +=  '       AND    S.'+dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,DataAreaId),DbBackend::Sql)+' = %2\n';
    sqlStmt     +=  '       AND    S.'+dictPriceDiscAdmTrans.fieldName(fieldNum(PriceDiscAdmTrans,Partition),DbBackend::Sql)+' = %4\n';
    sqlStmt     +=  '\n';
    sqlStmt     +=  'IF OBJECT_ID(N\'TEMPDB..#PRICEDISCTABLEREFTMP_%1\') IS NOT NULL\n';
    sqlStmt     +=  '   DROP TABLE #PRICEDISCTABLEREFTMP_%1\n';

    dataareaid = sqlSystem.sqlLiteral(curext());

    sqlStmt = strFmt(sqlStmt,
                     strFmt('%1_%2', sessionId(), DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),   // %1
        dataareaid,                                // %2
        sqlSystem.sqlLiteral(journalNum),          // %3
        getcurrentpartitionrecid());               // %4

    PriceDiscAdmSearch::executeStatement(sqlStmt);
}

private Query buildQuery()
{
    Query searchQuery = new Query();
    QueryBuildDataSource qbdsPriceDiscTable;

    qbdsPriceDiscTable = searchQuery.addDataSource(tableNum(PriceDiscTable));
    qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, relation)).value(queryValue(PriceType::PriceSales));
    qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, AccountCode)).value(queryValue(PriceDiscProductCodeType::All));
    qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, Currency)).value(currencyCode);

    if (toDate)
    {
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, FromDate)).value(queryRange(null, toDate));
    }
    if (fromDate)
    {
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, ToDate)).value(queryRange(fromDate, null));
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, ToDate)).value(queryValue(dateNull()));
    }
    if (priceAttributeGroupSearchTmp.PriceComponentCombination)
    {
        qbdsPriceDiscTable.addRange(fieldNum(PriceDiscTable, PriceComponentCombination)).value(queryValue(priceAttributeGroupSearchTmp.PriceComponentCombination));
    }

    this.addPriceDiscAdmTransDataSource(qbdsPriceDiscTable);

    return searchQuery;
}

/// <summary>
/// Joins the <c>PriceDiscAdmTrans</c> to the <c>PriceDiscTable</c> data source.
/// </summary>
/// <param name = "_qbdsPriceDiscTable"><c>PriceDiscTable</c> data source</param>
private void addPriceDiscAdmTransDataSource(QueryBuildDataSource _qbdsPriceDiscTable)
{
    QueryBuildDataSource qbdsPriceDiscAdmTrans = _qbdsPriceDiscTable.addDataSource(tableNum(PriceDiscAdmTrans));
    qbdsPriceDiscAdmTrans.relations(false);
    qbdsPriceDiscAdmTrans.fetchMode(QueryFetchMode::One2One);
    qbdsPriceDiscAdmTrans.joinMode(JoinMode::NoExistsJoin);
    qbdsPriceDiscAdmTrans.addRange(fieldNum(PriceDiscAdmTrans, JournalNum)).value(queryValue(journalNum));
    qbdsPriceDiscAdmTrans.addLink(fieldNum(PriceDiscTable, RecId), fieldNum(PriceDiscAdmTrans, PriceDiscTableRef), _qbdsPriceDiscTable.name());
}

public boolean unpack(container packedClass)
{
    Integer     version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;

        default:
            return false;
    }
    return true;
}
